L["Important Cast Color"] = "Цвет важного применения"
L["Tint the cast bar with the Important colour when the enemy casts a spell the game flags as important. Overrides the Interruptible Cast colour; your interrupt being on cooldown still takes priority."] = "Окрашивает полосу заклинаний в цвет важных заклинаний, когда противник кастует заклинание, помеченное игрой как важное. Приоритет выше цвета прерываемого каста; перезарядка вашего прерывания все еще в приоритете."
