-- Tooltips
L["Force boss debuffs into a single large column matched to the frame height (excluding cast bar), aligned to the chosen side of the frame. Overrides the Debuffs Location and Debuff Size settings while active. None disables it and uses the normal Debuffs Location."] = "Принудительно размещает дебаффы босса в одну большую колонку, соответствующую высоте рамки (исключая полосу заклинаний), выровненную по выбранной стороне рамки. При активности переопределяет настройки расположения и размера дебаффов. Вариант «Нет» отключает эту функцию и использует обычное расположение дебаффов."
L["Fades boss frames when the boss is out of range of your spells. Set to 100% to disable the fade."] = "Затемняет рамки боссов, когда босс находится вне зоны действия ваших заклинаний. Установите на 100% для отключения."
