L["Creates a class resource bar for Ignore Pain tracking. To see stack text, you must have Ignore Pain tracked in your Blizzard CDM \"Tracked Buffs\" or \"Tracked Bars\" section."] = "Создает полосу классового ресурса для отслеживания Стойкости к боли. Чтобы видеть текст стаков, у вас должно быть включено отслеживание Стойкости к боли в разделе «Отслеживаемые баффы» или «Отслеживаемые полосы» в Blizzard CDM."
