L["Shifts any elements anchored to the power bar up or down to offset the missing power bar. Applies both when the Power Bar is disabled and for specs that have no power (for example, Beast Mastery and Marksmanship Hunters, whose Focus shows as the class resource bar)."] = "Сдвигает любые элементы, привязанные к панели ресурса, вверх или вниз при отсутствии этой панели."
