L["This option can't be used while Shift Elements if No Resource is enabled."] = "Этот параметр нельзя использовать, если включено «Смещать элементы при отсутствии ресурса»."
L["This option requires a Health Text format other than None"] = "Этот параметр требует формата текста здоровья, отличного от «Нет»"
