L["Always display player coordinates centered below the minimap instead of only on hover."] = "Всегда показывать координаты игрока по центру под миникартой, а не только при наведении."
L["Display the clock inside the minimap instead of above it"] = "Отображать часы внутри миникарты вместо места над ней"
