L["Middle-click the minimap to open the EllesmereUI micro menu. When off, middle-click does nothing."] = "Клик средней кнопкой мыши по миникарте открывает микроменю EllesmereUI. Если отключено, клик ничего не делает."
L["New Mail"] = "Новое письмо"
L["Override the size of ungrouped minimap buttons independently from the interactable button size."] = "Переопределить размер неразгруппированных кнопок миникарты независимо от размера интерактивных кнопок."
L["Show black backgrounds behind minimap indicator buttons (tracking, calendar, mail, crafting, addon buttons, flyout toggle)."] = "Отображать черный фон под кнопками индикаторов миникарты (отслеживание, календарь, почта, профессии, кнопки аддонов, переключатель выдвижного меню)."
L["Size of addon minimap buttons in the flyout grid"] = "Размер кнопок аддонов в сетке выдвижного меню миникарты"
L["Size of mail, calendar, tracking, and minimap button group toggle"] = "Размер кнопок почты, календаря, отслеживания и переключателя группы кнопок миникарты"
L["When enabled, Shift+Click any minimap button (mail, calendar, tracking, addon buttons) to drag it to a custom position."] = "Если включено, зажав Shift+ЛКМ на любой кнопке миникарты (почта, календарь, отслеживание, кнопки аддонов), перетащите её в любое место."
L["When enabled, the extra buttons (Great Vault, M+ Portals, Friends Online, Group Button) and any ungrouped minimap buttons only show while the mouse is over the minimap. The M+ Portals flyout keeps them shown until it closes."] = "Если включено, дополнительные кнопки (Великое хранилище, Порталы M+, Друзья в сети, Кнопка группы) и любые неразгруппированные кнопки миникарты показываются только при наведении мыши на миникарту. Выдвижное меню порталов M+ удерживает их видимыми до закрытия."
