-- == Commit 0ec84f428688c76de71d1ae9088d536682b85cf3 Updates ==
L["Shadow Lily Preset"] = "Пресет Shadow Lily"
L["A new built-in profile preset: the damage dealer cut of Midnight Lily, a focused low-clutter layout that keeps your rotation and cooldowns front and center."] = "Новый встроенный пресет: версия Midnight Lily для бойцов. Минималистичный интерфейс, удерживающий ротацию и кулдауны в центре."
L["Class Resource Colors"] = "Цвета ресурсов класса"
L["Pick a custom color for each class resource such as combo points, runes, soul shards, and holy power, and color the class resource bar by your spec's resource with the new Class Resource Color fill mode."] = "Настройка цвета ресурсов класса (комбо-поинты, руны, осколки и др.) и окраска их полосы в цвет специализации в новом режиме заполнения."
L["Per-Spec Class Resource Bar"] = "Ресурсы классов по спекам"
L["The class resource bar gains a spec picker to choose which specs show it, matching the power and health bars."] = "Полоса классовых ресурсов получила выбор специализаций для отображения, аналогично полосам здоровья и ресурса."
L["Separate Cast Bar Texture"] = "Отд. текстура применения"
L["Choose a texture for the nameplate cast bar separately from the health bar."] = "Выбор текстуры полосы применения на индикаторах отдельно от полосы здоровья."
L["More Absorb Shield Textures"] = "Больше текстур поглощения"
L["Absorb shields gain several more stripe textures plus a tint color and an opacity setting that applies to every style."] = "Добавлены новые полосатые текстуры, настройки оттенка и прозрачности щитов поглощения для всех стилей."
L["Custom Uninterruptible Cast Color"] = "Цвет непрерываемых кастов"
L["Choose the color shown over uninterruptible casts on the target and focus cast bars, instead of the fixed grey."] = "Цвет неперерываемых кастов на полосах цели и фокуса вместо стандартного серого."
L["Charge cooldowns gain a per-spell Hide Recharge Edge option that removes the bright sweeping edge shown while a charge is recharging."] = "Удаление яркого кругового ободка при перезарядке способностей с зарядами."
L["Resize the Dispel Icon"] = "Размер значка рассеивания"
L["The dispel type icon gains an Icon Size slider in its cog menu so you can make it larger or smaller."] = "Иконка типа рассеиваемого эффекта получила ползунок размера в меню настроек."
L["Icicles"] = "Сосульки"
L["Maelstrom Weapon"] = "Оружие Водоворота"
L["Tip of the Spear"] = "Острие копья"
L["Whirlwind Stacks"] = "Заряды Вихря"
L["Show Cooldown Numbers"] = "Показ времени КД"
L["Reskin Great Vault"] = "Стиль Хранилища"
L["Reskin LFG Menu"] = "Стиль меню LFG"
L["Cast Bar Texture"] = "Текстура кастбара"
L["Health Bar Height"] = "Высота полосы здоровья"
L["Cast Bar Height"] = "Высота кастбара"
L["Dispel Icon"] = "Иконка рассеивания"
L["Empty Bar Overlay"] = "Фон пустых делений"
L["Bar Spacing"] = "Отступ полос"

-- Patch notes
L["You can now color the gaps between class resource pips and set the color and opacity of the empty slot overlay."] = "Можно настроить цвет промежутков между ресурсами класса, а также цвет и прозрачность пустого деления."
L["Health bars can now be up to 50 pixels tall and cast bars up to 40 pixels tall."] = "Высоту полос здоровья теперь можно увеличить до 50 пикселей, а кастбаров — до 40."
L["The interrupt flash now clears the instant a target dies, so the cast bar no longer looks squished by the death animation."] = "Вспышка прерывания исчезает при смерти цели, чтобы кастбар не сжимался анимацией смерти."
L["The spell picker now ends with a Missing Spells? shortcut that opens Blizzard's Cooldown Manager so you can add spells that are not listed."] = "В меню выбора заклинаний добавлен пункт «Нет заклинания?», открывающий Blizzard Cooldown Manager для добавления новых."
L["With Hide Active State on, a charge cooldown's recharge swipe and edge now stay visible instead of disappearing while a charge is in hand or when you press another ability."] = "При скрытии активного состояния анимация и граница заряда остаются видимыми, а не исчезают при наличии доступного заряда."
L["Switching specialization no longer briefly flashes placeholder icons across your tracked buff bars."] = "Смена специализации больше не вызывает мерцания временных иконок на панелях баффов."
L["Grouped tracking bars now stay anchored together when you enter combat instead of a member detaching from the group."] = "Сгруппированные полосы отслеживания больше не отделяются друг от друга при входе в бой."
L["Power-colored bars and power text now show the correct color on target, focus, and boss frames instead of white or a default color."] = "Полосы ресурса и их текст теперь окрашиваются в верный цвет на рамках цели, фокуса и боссов."
L["Abilities with multiple charges now show the recharge countdown number while charging when cooldown numbers are on, and you can toggle cooldown numbers from the Action Bars options."] = "Способности с зарядами отображают время восстановления при включенном КД, который можно настроить в панелях команд."
L["Fixed a taint issue with the chat box that could cause Lua errors, most often when receiving a whisper during combat."] = "Исправлен баг блокировки (taint) поля чата, приводивший к ошибкам Lua (чаще при получении сообщений в бою)."
L["Custom class, power, and resource colors no longer reset to default after switching specs or profiles."] = "Свои цвета классов, энергии и ресурсов больше не сбрасываются после смены спека или профиля."
L["Fade-Out Time"] = "Время исчезновения"

L["Colon (5:32)"] = "Двоеточие (5:32)"
L["Duration Format"] = "Формат длительности"
L["Seconds (152)"] = "Секунды (152)"
L["Standard (5m / 32)"] = "Стандарт (5m / 32)"
L["Header Bottom Border"] = "Нижняя граница заголовка"
L["Include Headerbar"] = "Включить панель заголовка"
L["Button Background"] = "Фон кнопки"
L["Button Border Style"] = "Стиль рамки кнопки"
-- Chat: sidebar and input field
