L["Add an action\n|cff66ccffLeft-click to pick an action from a list.\nYou can also drop an action from the cursor here.|r"] = "Добавить действие\n|cff66ccffЛевый клик, чтобы выбрать действие из списка.\nТакже можно перетащить действие сюда с курсора.|r"
L["Add in Blizzard CDM"] = "Добавить в Blizzard CDM" -- JARGAO
