L["Clickable links and player names on lines with shortened channel names now respond exactly where they appear, and the wheel scrolls into restored history right after a reload."] = "Кликабельные ссылки и имена игроков в строках с сокращёнными названиями каналов теперь реагируют точно там, где отображаются, а колесо прокрутки переходит в восстановленную историю сразу после перезагрузки интерфейса."
L["Clique controls click-casting on the same Raid Frames as EllesmereUI's HoverCast, so they conflict. Disable the Clique addon to use HoverCast."] = "Clique управляет кликовым применением заклинаний на тех же рейдовых рамках, что и HoverCast от EllesmereUI, поэтому они конфликтуют. Отключите аддон Clique, чтобы использовать HoverCast." -- JARGAO
