L["Controls where status icons are displayed. Use the individual settings to choose which icons are shown: Ready Check, Resurrection, Other Phase, or Other Party."] = "Управляет тем, где отображаются иконки статуса. Используйте отдельные настройки, чтобы выбрать, какие иконки показывать: проверка готовности, воскрешение, другая фаза или другая группа."
L["Controls where the incoming-summon icon is displayed, independent of the Status Icon slot above."] = "Управляет тем, где отображается иконка входящего призыва, независимо от ячейки иконки статуса выше."
L["Controls whether the Dead status text is displayed and where, independent of the Offline/AFK Status Text above."] = "Управляет тем, отображается ли и где текст статуса «Мёртв», независимо от текста статуса «Не в сети/AFK» выше."
L["Controls whether the Offline/AFK status text is displayed and where. Dead status text has its own independent settings below."] = "Управляет тем, отображается ли и где текст статуса «Не в сети/AFK». У текста статуса «Мёртв» есть свои независимые настройки ниже."
