L["Draw a 1px divider between the spell icon and the cast bar, matching the border color."] = "Рисовать разделитель в 1px между иконкой заклинания и полосой заклинаний, в цвет рамки."
L["Draw a filled background behind the text and border. Off draws the text and border on their own."] = "Рисовать заполненный фон за текстом и рамкой. При выключении текст и рамка рисуются отдельно."
L["Draw a solid one-pixel separator between the icon and cast bar when the icon is part of the bar."] = "Рисовать сплошной разделитель толщиной в один пиксель между иконкой и полосой заклинаний, когда иконка является частью панели."
L["Draw role icons behind the frame border, including the hover and target highlight."] = "Рисовать иконки ролей за рамкой, включая подсветку при наведении и выделение цели."
L["Draw tick lines across the bar at positions you choose."] = "Рисовать деления на полосе в выбранных вами позициях."
L["Draws a border around each pip instead of the bar as a whole."] = "Рисует рамку вокруг каждой точки вместо всей полосы целиком."
L["Draws a hash line that resets to the right edge when you cast Ignore Pain and slides left as the buff runs out."] = "Рисует хаш-линию, которая сбрасывается к правому краю при применении «Игнорирования боли» и сдвигается влево по мере истечения баффа."
L["Dream Flight\n(Cursor)"] = "Полёт снов\n(Курсор)" -- TODO: confirmar termo oficial
L["Dressing Room"] = "Примерочная"
L["Drop the individual Tab 1 / Tab 2 / Warbank Tab entries once the category list is doing the navigating. The consolidated views stay. Note that right-clicking a tab entry is the only way to rename a tab or change its deposit filters, so leave this off if you still need that."] = "Убрать отдельные пункты «Вкладка 1» / «Вкладка 2» / «Вкладка банка отряда», когда список категорий уже выполняет навигацию. Объединённые представления останутся. Обратите внимание: правый клик по пункту вкладки — единственный способ переименовать вкладку или изменить её фильтры депозита, поэтому оставьте это включённым, если вам это ещё нужно."
L["Drops columns nothing in this group can satisfy instead of greying them: no mage means no Intellect column, and a Mythic+ key means no Vantus. Turn off to keep every column in place whatever the group."] = "Убирает столбцы, которые никто в группе не может заполнить, вместо того чтобы делать их серыми: нет мага — нет столбца Интеллекта, есть ключ Mythic+ — нет Vantus. Отключите, чтобы столбцы оставались на месте независимо от состава группы."
L["Drops crests you own none of, keeping the block short early in a season. They stay listed in the tooltip."] = "Убирает слепки, которых у вас нет вообще, сохраняя блок компактным в начале сезона. Они остаются в списке подсказки."
