L["Keybinds set in EllesmereUI's own key fields now fire when two or more modifiers are held (for example Ctrl+Alt+1); re-bind any that never triggered."] = "Горячие клавиши, заданные в собственных полях клавиш EllesmereUI, теперь срабатывают при удержании двух и более модификаторов (например, Ctrl+Alt+1); перепривяжите те, что никогда не срабатывали."
