L["Left-click to set a keybind, then press any key or\nclick any mouse button to use it.\nEscape cancels. Right-click here to unbind."] = "Левый клик, чтобы назначить клавишу, затем нажмите любую клавишу или\nлюбую кнопку мыши, чтобы использовать её.\nEscape отменяет. Правый клик здесь снимает привязку."
