L["Not available in Dark Mode. Dark Mode colors can be adjusted in Global Settings -> Fonts & Colors."] = "Недоступно в тёмном режиме. Цвета тёмного режима можно настроить в «Глобальные настройки -> Шрифты и цвета»."
L["Not available while a legacy visibility value is selected. Pick Never or Always first."] = "Недоступно, пока выбрано устаревшее значение видимости. Сначала выберите «Никогда» или «Всегда»."
L["Not available while a spell on this bar uses a Cooldown State Shift Icons setting"] = "Недоступно, пока заклинание на этой панели использует настройку смещения иконок по состоянию перезарядки"
L["Not available while another bar overflows into this bar"] = "Недоступно, пока другая панель переполняется в эту панель"
L["Not available while this bar is anchored to another element"] = "Недоступно, пока эта панель привязана к другому элементу"
L["Not currently talented"] = "Сейчас талант не изучен"
L["Not in a guild"] = "Не в гильдии"
L["Not overridable"] = "Не переопределяется"
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies."] = "Не переопределяется. Эти условия общие и могут быть изменены, только пока не редактируется переопределение. Переопределение полностью заменяет настройку видимости — «Никогда», «Всегда» или «Наведение» — и игнорирует всё заданное здесь, пока применяется."
L["Not overridable. These conditions are shared and can only be changed while no override is being edited. An override replaces the Visibility setting outright -- Never, Always or Mouseover -- and ignores everything set here while it applies. Mouseover is sealed here too for this element: its hover mechanism follows the shared setting, so an override could only leave it shown."] = "Не переопределяется. Эти условия общие и могут быть изменены, только пока не редактируется переопределение. Переопределение полностью заменяет настройку видимости — «Никогда», «Всегда» или «Наведение» — и игнорирует всё заданное здесь, пока применяется. Наведение курсора также зафиксировано для этого элемента: механизм наведения следует общей настройке, поэтому переопределение может только оставить его показанным."
L["Not used in Icon display mode"] = "Не используется в режиме отображения иконки"
L["Nothing Extra"] = "Ничего дополнительного"
L["Nothing to add"] = "Нечего добавить"
L["November"] = "Ноябрь"
L["Nudge the bubble up or down from where the game put it. Zero sits exactly on Blizzard's own position, which is already over the speaker's head."] = "Сдвигает пузырь вверх или вниз от места, куда его поместила игра. Ноль совпадает точно с собственным положением Blizzard, которое уже находится над головой говорящего."
L["Nudge the cast bar up or down from its default spot under the health bar."] = "Сдвигает полосу заклинаний вверх или вниз от её стандартного места под полосой здоровья."
L["OH"] = "Левая рука"
L["OVERRIDES WARNING"] = "ПРЕДУПРЕЖДЕНИЕ О ПЕРЕОПРЕДЕЛЕНИЯХ"
L["October"] = "Октябрь"
L["Off (default): the cast bar fades with real transparency, matching the whole-frame Out of Range Alpha (best if you're colour-matching the frame and cast bar). On: the old behavior -- a black overlay dims the bar instead of fading it, which can't discolor a shielded/uninterruptible cast's tint but won't visually match the frame's fade."] = "Выкл. (по умолчанию): полоса заклинаний затухает с настоящей прозрачностью, соответствуя прозрачности вне дистанции всей рамки (лучше всего, если вы подбираете цвет рамки и полосы заклинаний). Вкл.: старое поведение — чёрное наложение затемняет полосу вместо затухания, что не может изменить оттенок защищённого/непрерываемого каста, но не будет визуально соответствовать затуханию рамки."
L["OffHandSlot"] = true
L["Offensive CDs"] = "Атакующие КД"
L["Offsets the base row's icon size in pixels from Icon Scale. The second row keeps the base size."] = "Смещает размер иконок базовой строки в пикселях от масштаба иконки. Вторая строка сохраняет базовый размер."
L["Offsets the bottom row's icon size in pixels from Icon Scale. The top row keeps the base size."] = "Смещает размер иконок нижней строки в пикселях от масштаба иконки. Верхняя строка сохраняет базовый размер."
L["Offsets the second row's icon size in pixels from Icon Scale. The base row keeps the base size."] = "Смещает размер иконок второй строки в пикселях от масштаба иконки. Базовая строка сохраняет базовый размер."
L["Offsets the top row's icon size in pixels from Icon Scale. The bottom row keeps the base size."] = "Смещает размер иконок верхней строки в пикселях от масштаба иконки. Нижняя строка сохраняет базовый размер."
L["On"] = "Вкл."
L["On (default): one profile's palette is shared across every profile (chosen via Pull Colors From). Off: each profile keeps its own custom colors (Power, Class Resource, Class, Resource)."] = "Вкл. (по умолчанию): палитра одного профиля используется во всех профилях (выбирается через «Брать цвета из»). Выкл.: каждый профиль сохраняет свои цвета (ресурс, ресурс класса, класс, ресурс)."
L["On Cooldown"] = "На перезарядке"
L["On Hover"] = "При наведении"
L["On Icon"] = "На иконке"
L["On My Way"] = "Уже иду"
L["On quest mobs in the open world, replaces the quest icon with the objective progress (ex: kill quests show 0/6, percentage objectives show 50%)."] = "У целей заданий в открытом мире заменяет иконку задания прогрессом цели (например, задания на убийство показывают 0/6, процентные цели показывают 50%)."
L["Once the lockout expires, show a Ready label on the icon in place of the countdown. The visibility rule above still applies."] = "Когда блокировка истекает, показывать на иконке метку «Готово» вместо обратного отсчёта. Правило видимости выше всё равно применяется."
L["One Button Assist Icon"] = "Иконка помощника «Одна кнопка»"
L["One Window"] = "Одно окно"
L["One Window combines everything into a single element; the Only choices show just that part."] = "«Одно окно» объединяет всё в один элемент; варианты «Только» показывают лишь эту часть."
L["One video walks you through the most important changes in 12.1 and how to get the most out of EllesmereUI under them. Copy the link and give it a watch before you dive in."] = "Одно видео проведёт вас через самые важные изменения в 12.1 и расскажет, как получить максимум от EllesmereUI с ними. Скопируйте ссылку и посмотрите его перед началом."
L["One-time copy of the Raid Frames Buff Manager filters into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Разовое копирование фильтров менеджера баффов рейдовых рамок в эти фильтры. Одноимённые фильтры ПЕРЕЗАПИСЫВАЮТСЯ; после этого два списка остаются раздельными."
L["One-time copy of your Player Aura Bars filter setups into these filters. Same-named filters are OVERWRITTEN; the two lists stay separate afterwards."] = "Разовое копирование настроек фильтров ваших панелей аур игрока в эти фильтры. Одноимённые фильтры ПЕРЕЗАПИСЫВАЮТСЯ; после этого два списка остаются раздельными."
L["Only Dispellable"] = "Только снимаемое"
L["Only Dispellable by You"] = "Только снимаемое вами"
L["Only Group & Pull"] = "Только группа и пул"
L["Only In Combat"] = "Только в бою"
L["Only Instant Casts"] = "Только мгновенные касты"
L["Only Markers"] = "Только метки"
L["Only Open MenuOut of Combat."] = "Открывать меню только вне боя."
L["Only Show Numbers"] = "Показывать только числа"
L["Only Show for % Health"] = "Показывать только для % здоровья"
L["Only Show in Housing"] = "Показывать только в доме" -- TODO: confirmar termo oficial
L["Only Show when Mounted"] = "Показывать только верхом"
L["Only Tracked Auras"] = "Только отслеживаемые ауры"
L["Only With Multiple Boss Frames"] = "Только при нескольких рамках боссов"
L["Only affects the vertical (Right/Left Edge) positions"] = "Влияет только на вертикальные положения (правый/левый край)"
L["Only applies when Name > Target is selected."] = "Применяется только при выбранном «Имя > Цель»."
L["Only applies when Name or Name > Target is selected."] = "Применяется только при выбранном «Имя» или «Имя > Цель»."
L["Only applies when the selected text includes a Name."] = "Применяется только когда выбранный текст включает имя."
L["Only available with the 'From' direction -- it highlights the pips at/above the threshold."] = "Доступно только с направлением «От» — подсвечивает точки на пороге и выше него."
L["Only color at/above threshold"] = "Окрашивать только на пороге и выше"
L["Only glow once the buff's stack count matches the comparison set via the gear."] = "Светиться только когда число стаков баффа соответствует сравнению, заданному в настройках."
L["Only if Power Bar Hidden"] = "Только если полоса ресурса скрыта"
L["Only in Combat"] = "Только в бою"
L["Only play alerts while in combat."] = "Воспроизводить оповещения только в бою."
L["Only preset or custom buff bars can be added to all specs"] = "Только пресетные или свои панели баффов можно добавить во все специализации"
L["Only recolor the fill when more than one boss frame is active at once (a multi-boss phase). With a single boss frame up, it keeps its normal color even while targeted. Off (default) recolors regardless of how many boss frames are active."] = "Перекрашивать заливку только когда активна более чем одна рамка босса одновременно (фаза с несколькими боссами). При одной активной рамке босса она сохраняет обычный цвет даже при выборе цели. Выкл. (по умолчанию) перекрашивает независимо от числа активных рамок боссов."
L["Only show buffs cast by you."] = "Показывать только баффы, наложенные вами."
L["Only show debuffs that have a duration, excluding permanent ones. Combines with the filters below; checked alone it shows every timed debuff."] = "Показывать только дебаффы с длительностью, исключая постоянные. Сочетается с фильтрами ниже; отдельно показывает все дебаффы с ограниченным временем."
L["Only show debuffs whose full duration is at most this many seconds. Combines with the filters; Unlimited applies no cap."] = "Показывать только дебаффы, чья полная длительность не превышает это число секунд. Сочетается с фильтрами; «Неограничено» не применяет ограничения."
L["Only show the GCD bar for instant-cast abilities. While hard-casting or channeling a spell, the bar stays hidden (the cast bar already shows that progress)."] = "Показывать панель GCD только для способностей с мгновенным применением. Во время обычного каста или ченнелинга заклинания панель остаётся скрытой (полоса заклинаний уже показывает этот прогресс)." -- JARGAO
L["Only show the GCD bar while in a dungeon, raid, arena or battleground."] = "Показывать панель GCD только в подземелье, рейде, на арене или поле боя." -- JARGAO
L["Only show the alert while in combat."] = "Показывать оповещение только в бою."
L["Only show the cast bar while a cast is in progress; hide it the rest of the time."] = "Показывать полосу заклинаний только во время каста; скрывать её всё остальное время."
L["Only show these buffs when you cast them."] = "Показывать эти баффы только когда вы их накладываете."
L["Only show this bar while the tracked buff/cooldown is active. Unchecked keeps an empty bar on screen at all times."] = "Показывать эту панель только пока отслеживаемый бафф/перезарядка активны. Без отметки пустая панель остаётся на экране всё время."
L["Only shows the GCD circle while you are in combat."] = "Показывает кольцо GCD только в бою." -- JARGAO
L["Only shows the cast bar circle while you are in combat."] = "Показывает кольцо полосы заклинаний только в бою."
L["Only shows the cursor circle while the mouse is hidden -- that is, while you hold the left and/or right mouse button to pan the camera or move your character."] = "Показывает кольцо курсора только когда мышь скрыта — то есть пока вы удерживаете левую и/или правую кнопку мыши для поворота камеры или движения персонажа."
L["Only shows the cursor circle while you are in combat."] = "Показывает кольцо курсора только в бою."
L["Only while AIRBORNE on a glide-capable mount or flight form. For the mount itself, ground included, use Skyriding Mount."] = "Только в воздухе на способном к планированию ездовом животном или в форме полёта. Для самого ездового животного, включая землю, используйте «Летающее ездовое животное»."
L["Only while airborne on a skyriding mount."] = "Только в воздухе на летающем ездовом животном."
L["Only works for Blizzard's whitelisted healer spell IDs (non-private auras)."] = "Работает только для ID заклинаний лекарей из белого списка Blizzard (не личные ауры)."
L["Only works outside of Instances"] = "Работает только вне подземелий"
L["Opacity of the Button Overlay tint."] = "Прозрачность тонировки наложения на кнопку."
L["Opacity of the background overlay. 0 removes it entirely; the 9.0.7 default is 62."] = "Прозрачность наложения фона. 0 полностью убирает его; значение по умолчанию из 9.0.7 — 62."
L["Opacity of the bar fill; below 100 the world shows through the fill instead of the background."] = "Прозрачность заливки полосы; ниже 100 мир просвечивает сквозь заливку вместо фона."
L["Opacity of the bar's background; the swatch picks the Modern color."] = "Прозрачность фона полосы; образец цвета выбирает цвет «Современный»."
L["Opacity of the cast bar fill; below 100 the world shows through the fill instead of the background."] = "Прозрачность заливки полосы заклинаний; ниже 100 мир просвечивает сквозь заливку вместо фона."
L["Opacity of the cooldown swipe (the dark radial sweep); use the swatch to set its colour."] = "Прозрачность заливки перезарядки (тёмная радиальная заливка); используйте образец цвета, чтобы задать её цвет."
L["Opacity of the resource fill; below 100 the world shows through the fill instead of the background."] = "Прозрачность заливки ресурса; ниже 100 мир просвечивает сквозь заливку вместо фона."
L["Opacity used for enemy nameplates outside the selected attack range."] = "Прозрачность, используемая для вражеских индикаторов вне выбранной дистанции атаки."
L["Open At"] = "Открывать в"
L["Open Bags"] = "Открыть сумки"
L["Open Character Sheet"] = "Открыть окно персонажа"
L["Open Currencies"] = "Открыть валюты"
L["Open Edit Mode"] = "Открыть режим редактирования"
L["Open Great Vault"] = "Открыть Великое хранилище"
L["Open Profession"] = "Открыть профессию"
L["Open Profession Book"] = "Открыть книгу профессии"
L["Open Settings"] = "Открыть настройки"
L["Open Talents"] = "Открыть таланты"
L["Open World"] = "Открытый мир"
L["Open World Basic Coloring"] = "Базовая окраска открытого мира"
L["Open it anytime from the EUI Options Sidebar."] = "Открывайте в любой момент из боковой панели настроек EUI."
L["Opening Myslot again forces every bar visible, including bars using Match Any, Hide with Target or the mounted visibility conditions."] = "Повторное открытие Myslot принудительно показывает все панели, включая панели с условиями «Совпадение любого», «Скрыть с целью» или условиями видимости верхом."
L["Opens"] = "Открывает"
L["Options Panel"] = "Панель настроек"
L["Order"] = "Порядок"
L["Order of the buttons on this bar; corner options place the first button in that corner."] = "Порядок кнопок на этой панели; варианты углов размещают первую кнопку в этом углу."
L["Organizes your friends list into collapsible custom groups."] = "Организует список друзей в сворачиваемые собственные группы."
L["Others are missing my buff"] = "Другим не хватает моего баффа"
L["Others are missing my buff: remind when a groupmate is missing a buff you can cast.\nI am missing others' buffs: remind when you are missing a buff a groupmate could give you (only shown when someone who can cast it is present). Off by default."] = "«Другим не хватает моего баффа»: напоминать, когда у товарища по группе нет баффа, который вы можете наложить.\n«Мне не хватает чужих баффов»: напоминать, когда у вас нет баффа, который может дать товарищ по группе (показывается только когда присутствует тот, кто может его наложить). По умолчанию отключено."
L["Out of Boss Combat"] = "Вне боя с боссом"
L["Out of Combat Alpha"] = "Прозрачность вне боя"
L["Out of Combat Color"] = "Цвет вне боя"
L["Out of Combat Opacity"] = "Непрозрачность вне боя"
L["Out of Combat Settings"] = "Настройки вне боя"
L["Out of Range Opacity"] = "Прозрачность вне дистанции"
L["Out-of-range coloring now tracks the spell actually on the icon while a proc or talent override replaces it, instead of the base spell's range."] = "Окраска вне дистанции теперь отслеживает заклинание, реально находящееся на иконке, пока прок или переопределение талантом заменяет его, вместо дистанции базового заклинания."
L["Out-of-range frames darken instead of fading transparent, matching Blizzard's default party/raid frame look. Uses the same Out of Range Alpha % as brightness: 100% = no visible difference in/out of range, 10% = out-of-range frames drop to 10% brightness."] = "Рамки вне дистанции темнеют вместо затухания в прозрачность, соответствуя стандартному виду групповых/рейдовых рамок Blizzard. Использует тот же % прозрачности вне дистанции как яркость: 100% = нет видимой разницы в/вне дистанции, 10% = рамки вне дистанции падают до 10% яркости."
L["Outfit"] = "Образ"
L["Outfits"] = "Образы"
L["Outline style override for all %1$s text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста %1$s. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Action Bars text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста панелей действий. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all AuraBuff Reminders text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста напоминаний аур/баффов. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Bags text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста сумок. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Blizz UI Enhanced text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста улучшенного интерфейса Blizzard. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Chat text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста чата. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Cooldown Manager text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста менеджера перезарядки. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Damage Meters text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста счётчиков урона. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all DataBars text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста полос данных. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Friends List text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста списка друзей. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
L["Outline style override for all Minimap text. EUI Global Outline follows the global Outline Mode setting above."] = "Переопределение стиля обводки для всего текста миникарты. «Глобальная обводка EUI» следует глобальной настройке режима обводки выше."
