L["Recolor the bar while you have a buff. The first active buff in the list wins, so order = priority. Overrides threshold coloring while active.\nYou must be tracking the buff in Blizzard CDM, added to EUI CDM, and this only works with CDM trackable buffs."] = "Перекрашивать полосу, пока у вас есть бафф. Побеждает первый активный бафф в списке, поэтому порядок = приоритет. Переопределяет окраску по порогу, пока активна.\nВы должны отслеживать бафф в CDM Blizzard, добавленный в CDM EUI, и это работает только с баффами, отслеживаемыми через CDM." -- JARGAO
L["Recolor the countdown text below Threshold Seconds."] = "Перекрашивать текст обратного отсчёта ниже порога секунд."
