L["Recolors this boss frame's health bar fill with the color chosen below while it is your current target. Boss frames only."] = "Перекрашивает заливку полосы здоровья этой рамки босса в выбранный ниже цвет, пока он является вашей текущей целью. Только рамки боссов."
