L["Reset failed - there are still players inside the instance."] = "Сброс не удался — в подземелье всё ещё есть игроки."
L["Resize Blizzard's default game text from 75-125%"] = "Изменение размера стандартного игрового текста Blizzard от 75 до 125%"
L["Reskin Extra Action Buttons"] = "Переоформить дополнительные кнопки действий"
