L["Sets the font for the names that float above players, NPCs and enemies in the world.\n\nSeparate from Global Font - changing this does not affect the rest of the UI, and Global Font does not affect it.\n\nBlizzard Default leaves the name text completely untouched.\n\n|cffff4d4dRequires a re-log or restart of WoW to take effect.|r"] = "Задаёт шрифт для имён, плавающих над игроками, NPC и врагами в мире.\n\nОтдельно от глобального шрифта — изменение этого не влияет на остальной интерфейс, а глобальный шрифт не влияет на это.\n\n«Blizzard по умолчанию» оставляет текст имени полностью нетронутым.\n\n|cffff4d4dТребует перезахода или перезапуска WoW, чтобы вступить в силу.|r"
