L["Square or Rectangular Shape"] = "Квадратная или прямоугольная форма"
L["Squares the extra action and zone ability buttons and gives them a thin black border.\n\nOff by default. The size slider below works whether this is on or off."] = "Делает кнопки дополнительного действия и способности зоны квадратными и добавляет им тонкую чёрную рамку.\n\nПо умолчанию отключено. Ползунок размера ниже работает независимо от того, включено это или нет."
