L["Support Team"] = "Команда поддержки"
L["Suppresses \"You have learned a new spell/ability/passive effect\" and \"You have unlearned ...\" system messages, like the ones spammed every time you switch spec or talent loadout."] = "Подавляет системные сообщения «Вы изучили новое заклинание/способность/пассивный эффект» и «Вы забыли ...», подобные тем, что спамятся при каждой смене специализации или набора талантов."
L["Suppresses right click targeting. Enemies applies everywhere. Allies In Combat only suppresses friendly targets while you are in combat, so you can still right click vendors and NPCs out of combat.\n\nNote: while this is active, holding Left+Right click to move forward won't work if your cursor is over a suppressed nameplate/unit, since this feature has to take over the right mouse button entirely to block targeting."] = "Подавляет выбор цели правым кликом. «Враги» применяется везде. «Союзники в бою» подавляет только дружественные цели, пока вы в бою, поэтому вы всё ещё можете кликать правой кнопкой по торговцам и NPC вне боя.\n\nПримечание: пока это активно, удержание левой+правой кнопки для движения вперёд не сработает, если курсор над подавленным индикатором/юнитом, так как эта функция должна полностью перехватить правую кнопку мыши, чтобы заблокировать выбор цели."
L["Swap Combat Potions When Missing"] = "Заменять боевые зелья при отсутствии"
L["Swap Light/Reckless Pots When Missing"] = "Заменять лёгкие/безрассудные зелья при отсутствии"
L["Sweeping Strikes"] = "Круговые удары" -- TODO: confirmar termo oficial
L["Swipe Class Colored"] = "Заливка в цвет класса"
L["Swipe Color"] = "Цвет заливки"
L["Switch At"] = "Переключать при"
L["Switch Blizzard's chat bubbles off for as long as you are inside a dungeon, raid, scenario or battleground, and back on the way out.\n\nEllesmereUI never restyles bubbles inside an instance: the game's bubble frames are off limits to addons there. This decides whether Blizzard's own are visible at all."] = "Отключает пузыри чата Blizzard, пока вы находитесь в подземелье, рейде, сценарии или поле боя, и включает их обратно на выходе.\n\nEllesmereUI никогда не переоформляет пузыри внутри группового содержимого: рамки пузырей игры там недоступны для аддонов. Это решает, видны ли вообще собственные пузыри Blizzard."
L["Switch back to Blizzard's bars."] = "Переключиться обратно на панели Blizzard."
L["Switch to Experience"] = "Переключиться на опыт"
L["Switch to Reputation"] = "Переключиться на репутацию"
L["Switch to a spec in this group to customize its Unlock Mode"] = "Переключитесь на специализацию в этой группе, чтобы настроить её режим разблокировки"
L["Sync Border with Chat Panel"] = "Синхронизировать рамку с панелью чата"
L["Sync From"] = "Синхронизировать из"
L["Sync Generic CDs/Buffs"] = "Синхронизировать общие КД/баффы"
L["Sync Racials, Pots & Trinkets"] = "Синхронизировать расовые, зелья и аксессуары"
L["Sync Segment Selection"] = "Синхронизировать выбор сегмента"
L["Sync cleared -- fewer than two specs remained selected."] = "Синхронизация очищена — осталось выбрано меньше двух специализаций."
L["Sync cleared -- only one spec was selected. Tick at least two specs (including other characters' specs) to sync between them."] = "Синхронизация очищена — была выбрана только одна специализация. Отметьте хотя бы две специализации (включая специализации других персонажей), чтобы синхронизировать их между собой."
L["Synced with Simple Mode"] = "Синхронизировано с простым режимом"
L["Syncing generic CDs/buffs across %d specs. Icon order is not synced -- each spec keeps its own arrangement."] = "Синхронизация общих КД/баффов между %d специализациями. Порядок иконок не синхронизируется — каждая специализация сохраняет свою расстановку."
