L["Tint an entry that would do nothing right now: red when the target is out of range, blue when you are short of the resource, and gray when the game refuses it for any other reason. Spells and items only -- the game reports every toy as unusable, and a macro's usability depends on what its body resolves to."] = "Тонировать запись, которая сейчас ничего не сделает: красным, когда цель вне дистанции, синим, когда не хватает ресурса, и серым, когда игра отказывает по другой причине. Только заклинания и предметы — игра сообщает о каждой игрушке как о неиспользуемой, а применимость макроса зависит от того, во что разрешается его тело."
L["Tint the bar with the Important colour when the enemy casts a spell the game flags as important."] = "Тонировать панель цветом «Важное», когда враг применяет заклинание, которое игра помечает как важное."
L["Tint the cast bar with the Important colour when the unit casts a spell the game flags as important. Your interrupt being on cooldown still takes priority."] = "Тонировать полосу заклинаний цветом «Важное», когда юнит применяет заклинание, которое игра помечает как важное. Ваше прерывание на перезарядке всё равно имеет приоритет."
L["Tint the combat icon by the member's class color. Not available for the Arcade/Dungeoneer/Classic/Cross/Circle/Square styles."] = "Тонировать боевую иконку цветом класса участника. Недоступно для стилей «Аркада»/«Исследователь»/«Классика»/«Крест»/«Круг»/«Квадрат»."
L["Tints the pattern with the bar's current color instead of the custom overlay color."] = "Тонирует узор текущим цветом полосы вместо своего цвета наложения."
L["Tints this block's slot with its own color."] = "Тонирует ячейку этого блока собственным цветом."
