L["What sits in front of the number. Icon shows the character icon; the color swatches on the left tint it."] = "Что находится перед числом. «Иконка» показывает иконку персонажа; образцы цвета слева тонируют её."
L["What's new in EllesmereUI."] = "Что нового в EllesmereUI."
