L["Width %"] = "Ширина %"
L["Width matched to CDM: Cooldowns. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с CDM: Кулдауны. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to Cast Bar. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с полосой заклинаний. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to Class Resource. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с ресурсом класса. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to GCD Bar. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с панелью GCD. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to Health Bar. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с полосой здоровья. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to Player Frame. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с рамкой игрока. Отмените сопоставление в режиме разблокировки для редактирования."
L["Width matched to Power Bar. Unmatch in Unlock Mode to edit."] = "Ширина сопоставлена с полосой ресурса. Отмените сопоставление в режиме разблокировки для редактирования."
