L["Window header, bar and timer text"] = "Текст заголовка окна, полосы и таймера"
L["Window scale, icon zoom and item level settings are shared with the Bags page."] = "Настройки масштаба окна, увеличения иконок и уровня предметов совпадают со страницей сумок."
L["Window skins are currently disabled for this profile."] = "Оформление окон сейчас отключено для этого профиля."
L["Window skins are now disabled for this profile. A UI reload is required to restore the stock Blizzard windows."] = "Оформление окон теперь отключено для этого профиля. Требуется перезагрузка интерфейса, чтобы восстановить стандартные окна Blizzard."
L["Window skins are now enabled for this profile. A UI reload is required to apply them."] = "Оформление окон теперь включено для этого профиля. Требуется перезагрузка интерфейса, чтобы применить его."
L["Window skins changed for this profile. A UI reload is needed to apply them."] = "Оформление окон изменено для этого профиля. Для применения требуется перезагрузка интерфейса."
L["Windrush Totem\n(Cursor)"] = "Тотем свежего ветра\n(Курсор)" -- TODO: confirmar termo oficial
L["With health decimals on, full health renders 100% instead of 100.0% while real decimals like 99.5% stay"] = "При включённых десятичных знаках здоровья полное здоровье отображается как 100% вместо 100.0%, а настоящие десятичные значения вроде 99.5% сохраняются"
L["With the Rectangular shape, player and party arrows no longer draw in the hidden bands above and below the map, and combat transitions no longer leave the map cut off wrong."] = "При прямоугольной форме стрелки игрока и группы больше не отрисовываются в скрытых полосах выше и ниже карты, а переходы боя больше не обрезают карту неправильно."
L["WoW Token"] = "Жетон WoW" -- TODO: confirmar termo oficial
L["Works in and out of combat, unlike Auto-Repair. When a group-wide raid buff's column header shows it's missing on someone, the icon blinks and sends the buff's spell link. In a raid, left-click reaches a provider in groups 1-4 and right-click one in groups 5-8; outside a raid, left-click reaches the only provider found. Hovering the icon always shows who each click would whisper, or that everyone already has it."] = "Работает как в бою, так и вне боя, в отличие от Автопочинки. Когда заголовок столбца общерейдового баффа показывает, что у кого-то его нет, иконка мигает и отправляет ссылку на заклинание баффа. В рейде клик левой кнопкой обращается к источнику в группах 1-4, а клик правой кнопкой — в группах 5-8; вне рейда клик левой кнопкой обращается к единственному найденному источнику. Наведение на иконку всегда показывает, кому будет отправлен шёпот при каждом клике, или что баффом уже обладают все."
