L["Your Edit Mode layout is a Blizzard preset which cannot be modified by addons. Please switch to a custom Edit Mode layout so EllesmereUI can manage your CDM settings.\n\nOpen Edit Mode to create or select a custom layout."] = "Ваша раскладка режима редактирования — это пресет Blizzard, который аддоны не могут изменять. Переключитесь на пользовательскую раскладку режима редактирования, чтобы EllesmereUI мог управлять вашими настройками CDM.\n\nОткройте режим редактирования, чтобы создать или выбрать пользовательскую раскладку."
