L["Your current spec has its own custom Buff Manager, so conditional Buff Managers never apply to it."] = "У вашей текущей специализации есть собственный менеджер баффов, поэтому условные менеджеры баффов никогда к ней не применяются."
L["Your current spec has its own custom Debuff Manager, so conditional Debuff Managers never apply to it."] = "У вашей текущей специализации есть собственный менеджер дебаффов, поэтому условные менеджеры дебаффов никогда к ней не применяются."
L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "У вашей текущей специализации есть собственный режим разблокировки, поэтому условные режимы разблокировки никогда к ней не применяются. Переключитесь на специализацию без него, чтобы настроить это."
